/**
 * Default_Ignorable_Code_Point members that are renderable BY CATEGORY: the
 * variation selectors, and the fillers / joiners / inherent vowels that Unicode
 * classes as `Mn` or `Lo` while specifying that they render as nothing.
 *
 * Without these the allowlist would admit U+FE0F and U+3164, and two titles could
 * be pixel-identical while folding to different keys — one of them a name nobody
 * can retype.
 */
export const NAME_DEFAULT_IGNORABLE_RANGES: readonly (readonly [number, number])[] = [
  [0x034F, 0x034F], // COMBINING GRAPHEME JOINER
  [0x115F, 0x1160], // HANGUL CHOSEONG FILLER..HANGUL JUNGSEONG FILLER
  [0x17B4, 0x17B5], // KHMER VOWEL INHERENT AQ..KHMER VOWEL INHERENT AA
  [0x180B, 0x180D], // MONGOLIAN FREE VARIATION SELECTOR ONE..MONGOLIAN FREE VARIATION SELECTOR THREE
  [0x180F, 0x180F], // MONGOLIAN FREE VARIATION SELECTOR FOUR
  [0x3164, 0x3164], // HANGUL FILLER
  [0xFE00, 0xFE0F], // VARIATION SELECTOR-1..VARIATION SELECTOR-16
  [0xFFA0, 0xFFA0], // HALFWIDTH HANGUL FILLER
  [0xE0100, 0xE01EF], // VARIATION SELECTOR-17..VARIATION SELECTOR-256
];

